<?php
namespace App\Http\Controllers;use App\Models\{Event,News,Setting,Department};class HomeController extends Controller{public function __invoke(){return view('home',['news'=>News::published()->latest('published_at')->limit(3)->get(),'events'=>Event::published()->upcoming()->orderBy('starts_at')->limit(4)->get(),'departments'=>Department::where('is_active',true)->orderBy('sort')->limit(7)->get(),'stats'=>['founded'=>Setting::valueOf('founded_year','1958'),'students'=>Setting::valueOf('students_count'),'teachers'=>Setting::valueOf('teachers_count'),'departments'=>Setting::valueOf('departments_count')]]);}}